    34	/**
    35	 * Build the correct stack order for `onboardingModalNavigator`,
    36	 * based on onboarding data (currently from the selected purpose).
    37	 * The correct stack order will ensure that navigation and
    38	 * the `goBack` navigatoin work properly.
    39	 */
    40	function adaptOnboardingRouteState() {
    41	    const currentRoute: NavigationPartialRoute | undefined = navigationRef.getCurrentRoute();
    42	    if (!currentRoute || currentRoute?.name === SCREENS.ONBOARDING.PURPOSE) {
    43	        return;
    44	    }
    45	
    46	    const rootState = navigationRef.getRootState();
    47	    const adaptedState = rootState;
    48	    const lastRouteIndex = (adaptedState?.routes?.length ?? 0) - 1;
    49	    const onBoardingModalNavigatorState = adaptedState?.routes[lastRouteIndex]?.state;
    50	    if (!onBoardingModalNavigatorState || onBoardingModalNavigatorState?.routes?.length > 1) {
    51	        return;
    52	    }
    53	
    54	    let adaptedOnboardingModalNavigatorState = {} as Readonly<PartialState<NavigationState>>;
    55	    if (currentRoute?.name === SCREENS.ONBOARDING.PERSONAL_DETAILS && selectedPurpose === CONST.ONBOARDING_CHOICES.MANAGE_TEAM) {
    56	        adaptedOnboardingModalNavigatorState = {
    57	            index: 2,
    58	            routes: [
    59	                {
    60	                    name: SCREENS.ONBOARDING.PURPOSE,
    61	                    params: currentRoute?.params,
    62	                },
    63	                {
    64	                    name: SCREENS.ONBOARDING.WORK,
    65	                    params: currentRoute?.params,
    66	                },
    67	                {...currentRoute},
    68	            ],
    69	        } as Readonly<PartialState<NavigationState>>;
    70	    } else {
    71	        adaptedOnboardingModalNavigatorState = {
    72	            index: 1,
    73	            routes: [
    74	                {
    75	                    name: SCREENS.ONBOARDING.PURPOSE,
    76	                    params: currentRoute?.params,
    77	                },
    78	                {...currentRoute},
    79	            ],
    80	        } as Readonly<PartialState<NavigationState>>;
    81	    }
    82	
    83	    adaptedState.routes[lastRouteIndex].state = adaptedOnboardingModalNavigatorState;
    84	    navigationRef.resetRoot(adaptedState);
    85	}
    86	
    87	/**
    88	 * Start a new onboarding flow or continue from the last visited onboarding page.
    89	 */
    90	function startOnboardingFlow() {
    91	    const currentRoute = navigationRef.getCurrentRoute();
    92	    const {adaptedState} = getAdaptedStateFromPath(getOnboardingInitialPath(), linkingConfig.config, false);
    93	    const focusedRoute = findFocusedRoute(adaptedState as PartialState<NavigationState<RootStackParamList>>);
    94	    if (focusedRoute?.name === currentRoute?.name) {
    95	        return;
    96	    }
    97	    navigationRef.resetRoot(adaptedState);
    98	}
    99	
   100	function getOnboardingInitialPath(): string {
   101	    const state = getStateFromPath(onboardingInitialPath, linkingConfig.config);
   102	    if (state?.routes?.at(-1)?.name !== NAVIGATORS.ONBOARDING_MODAL_NAVIGATOR) {
   103	        return `/${ROUTES.ONBOARDING_ROOT.route}`;
   104	    }
   105	
   106	    return onboardingInitialPath;
   107	}
   108	
   109	function clearInitialPath() {
   110	    onboardingInitialPath = '';
   111	}
   112	
   113	/**
   114	 * Onboarding flow: Go back to the previous page.
   115	 * Since there is no `initialRoute` for `onBoardingModalNavigator`,
   116	 * firstly, adjust the current onboarding modal navigator to establish the correct stack order.
   117	 * Then, navigate to the previous onboarding page using the usual `goBack` function.
   118	 */
   119	function goBack() {
   120	    adaptOnboardingRouteState();
   121	    Navigation.isNavigationReady().then(() => {
   122	        Navigation.goBack();
   123	    });
   124	}
   125	
   126	export {getOnboardingInitialPath, startOnboardingFlow, clearInitialPath, goBack};
